function togglePresetOverride(id){let work=W.find(w=>w.id===id);if(!work)return;if(doiBenchmark&&!work.doi){alert('DOI benchmark mode requires a DOI. Turn off that mode to include this work.');return}presetOverrides.has(id)?presetOverrides.delete(id):presetOverrides.add(id);screenHistory.push({action:presetOverrides.has(id)?'preset_override_include':'preset_override_remove',work_id:id,at:new Date().toISOString()});E('kn').innerText=cur().length.toLocaleString();updateCorpusSummary();renderScreenRows()}
function updateCorpusSummary(){let el=E('corpusSummary');if(!el)return;let counts=Object.keys(BiblioMapCorpus.names).map(id=>[id,W.filter(w=>BiblioMapCorpus.evaluate(w,id,doiBenchmark).status==='included').length]);let decisions=W.map(w=>BiblioMapCorpus.evaluate(w,corpusPreset,doiBenchmark));let excluded=decisions.filter(d=>d.status==='excluded').length,unknown=decisions.filter(d=>d.status==='unknown').length,why={},flags={};decisions.forEach(d=>{d.reasons.forEach(r=>why[r]=(why[r]||0)+1);d.flags.forEach(r=>flags[r]=(flags[r]||0)+1)});el.innerHTML='<div class="corpus-counts">'+counts.map(([id,n])=>'<span><b>'+n.toLocaleString()+'</b> '+esc(BiblioMapCorpus.names[id])+'</span>').join('')+'</div><div class="note">'+excluded.toLocaleString()+' excluded by preset · '+unknown.toLocaleString()+' need source/metadata verification · '+presetOverrides.size.toLocaleString()+' work-level overrides. Counts use only retrieved works; records remain in the saved search.</div>'+(unknown?'<div class="note">Unknown works are held out of this preset until their metadata is verified. Older snapshots may need a fresh search.</div>':'')+'<details><summary>Why works are excluded</summary>'+Object.entries(why).sort((a,b)=>b[1]-a[1]).map(([r,n])=>'<div class="frow"><span>'+esc(r)+'</span><b>'+n.toLocaleString()+'</b></div>').join('')+'</details><details><summary>Metadata and provenance flags</summary>'+Object.entries(flags).sort((a,b)=>b[1]-a[1]).map(([r,n])=>'<div class="frow"><span>'+esc(r)+'</span><b>'+n.toLocaleString()+'</b></div>').join('')+'</details><div class="note">These are transparent selection rules for citation analysis, not a measure of research quality or a validated Scopus/Web of Science classifier. DOI and abstract are never required unless DOI benchmark mode is selected.</div>'}
