function bulkScreen(exclude){let matches=W.filter(screenMatches),affected=matches.filter(w=>screenExcluded.has(w.id)!==exclude);if(!affected.length)return;pendingBulk={exclude,matched:matches.length,works:affected,filters:{text:screenQuery,...screenFilters}};let overlay=document.createElement('div');overlay.id='bulkPreview';overlay.className='name-overlay';let action=exclude?'Exclude':'Restore';overlay.innerHTML='<div class="name-dialog bulk-dialog" role="dialog" aria-modal="true" aria-labelledby="bulkTitle"><h2 id="bulkTitle">Review '+action.toLowerCase()+' action</h2><p>'+action+' <b>'+affected.length.toLocaleString()+'</b> of '+matches.length.toLocaleString()+' matching works across all pages. Check the list before applying.</p><div class="bulk-preview-list">'+affected.map(w=>'<div class="bulk-preview-item"><b>'+esc(w.display_name||'Untitled work')+'</b><small>'+esc(w.publication_year||'—')+' · '+esc(w.type||'Unknown type')+' · '+esc(w.primary_location?.source?.display_name||'Unknown source')+'</small></div>').join('')+'</div><div class="actions"><button type="button" class="ghost" onclick="closeBulkPreview()">Cancel</button><button type="button" class="'+(exclude?'exclude':'keep')+'" onclick="confirmBulkScreen()">'+action+' '+affected.length.toLocaleString()+' '+(affected.length===1?'work':'works')+'</button></div></div>';overlay.addEventListener('keydown',e=>{if(e.key==='Escape')closeBulkPreview()});document.body.appendChild(overlay);overlay.querySelector('button').focus()}
